/*
 * Runtime symbol-stability contract for Calendar Plus components.
 *
 * These version nodes prevent accidental package-internal ABI regressions.
 * They do not by themselves define a supported external C SDK; source-neutral
 * core headers are intentionally not installed by the runtime package.
 */

